def sse_events(decoder: SSEDecoder, chunks: list[bytes]) -> list[dict[str, Any]]:
    events = [event for chunk in chunks for event in decoder.feed(chunk)]
    events.extend(decoder.close())
    result: list[dict[str, Any]] = []
    for event in events:
        item: dict[str, Any] = {"event": event.event, "data": event.data, "id": event.id or None}
        if event.retry is not None:
            item["retry"] = event.retry
        result.append(item)
    return result


