@pytest.mark.parametrize("case", cases("chat_stream"))
def test_chat_stream_accumulation(case: dict[str, Any]) -> None:
    expect = case["expect"]
    headers = httpx.Headers(case["headers"])
    accumulator = ChatAccumulator(dialog_id=headers.get("x-dialog-id"), turn_no=int(headers["x-turn-no"]))
    decoder = SSEDecoder()
    frames = [*decoder.feed(case["raw"].encode("utf-8")), *decoder.close()]
    types: list[str] = []
    for frame in frames:
        if frame.event == "ping" or frame.data == "":
            continue
        event: ChatEvent = validate(ChatEvent, json.loads(frame.data))
        types.append(event.to_dict()["type"])
        accumulator.add(event)
    result = accumulator.result()
    assert result.dialog_id == expect["dialog_id"]
    assert result.turn_no == expect["turn_no"]
    assert result.text == expect["text"]
    assert result.stop_reason == expect["stop_reason"]
    assert result.cost_tiyn == expect["cost_tiyn"]
    assert (result.usage.to_dict() if result.usage is not None else None) == expect["usage"]
    assert result.choice_id == expect["choice_id"]
    assert len(result.events) == expect["event_count"]
    if "event_types" in expect:
        assert types == expect["event_types"]
    if expect["error"] is None:
        accumulator.raise_for_error()
        assert result.error is None
    else:
        with pytest.raises(ChatStreamError) as caught:
            accumulator.raise_for_error()
        error = caught.value
        assert (error.type, error.code, error.message, error.request_id) == (
            expect["error"]["type"],
            expect["error"]["code"],
            expect["error"]["message"],
            expect["error"]["request_id"],
        )
        assert error.extra == expect["error"]["extra"]
        assert error.result is not None
        assert error.result.text == expect["text"]
